1	// Контракт серверного модуля «Монетки» (games/coin/spec.md, SC-10; platform/sdk/types.ts).
2	// Проверяются только публичные методы GameModule и их результат, без опоры на внутреннее устройство.
3	import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
4	import game from '../server/index.ts';
5	import { GameError } from '../../../platform/sdk/types.ts';
6	
7	/** rng, который отдаёт заданные числа и бросает, когда они кончились; считает вызовы. */
8	function countingRng(values: number[]) {
9	  let calls = 0;
10	  const rng = {
11	    next(): number {
12	      calls += 1;
13	      if (calls > values.length) throw new Error('rng: лишний вызов');
14	      return values[calls - 1] as number;
15	    },
16	  };
17	  return { rng, calls: () => calls };
18	}
19	
20	function gameErrorCode(fn: () => unknown): string {
21	  try {
22	    const v = fn();
23	    throw new Error(`ожидалась GameError, а вызов вернул ${JSON.stringify(v)}`);
24	  } catch (e: any) {
25	    expect(e).toBeInstanceOf(GameError);
26	    return e.code;
27	  }
28	}
29	
30	describe('Монетка: контракт модуля игры', () => {
31	  beforeEach(() => {
32	    vi.spyOn(Math, 'random').mockImplementation(() => {
33	      throw new Error('Math.random запрещён в игре');
34	    });
35	  });
36	  afterEach(() => {
37	    vi.restoreAllMocks();
38	  });
39	
40	  it('SC-10: id и validateParams нормализуют параметры до { side }', () => {
41	    expect(game.id).toBe('coin');
42	    expect(game.validateParams({ side: 'tails', x: 1 })).toEqual({ side: 'tails' });
43	    expect(game.validateParams({ side: 'heads' })).toEqual({ side: 'heads' });
44	  });
45	
46	  it('SC-10: validateParams бросает GameError INVALID_PARAMS на неверные параметры', () => {
47	    for (const p of [{ side: 'edge' }, { side: 'HEADS' }, { side: 1 }, {}, null, undefined, 'heads', ['heads'], 42]) {
48	      expect(gameErrorCode(() => game.validateParams(p)), `params = ${JSON.stringify(p)}`).toBe('INVALID_PARAMS');
49	    }
50	  });
51	
52	  it('SC-10: start закрывает раунд одним вызовом rng, состояние сериализуемо, publicView = { side, outcome, win }', () => {
53	    const { rng, calls } = countingRng([0.75]);
54	    const step: any = game.start({ bet: 4, params: { side: 'tails' }, rng });
55	    expect(calls()).toBe(1);
56	    expect(step.status).toBe('finished');
57	    expect(step.state).toEqual({ side: 'tails', outcome: 'tails', win: true });
58	    expect(step.payout).toBeCloseTo(7.84, 9);
59	    expect(JSON.parse(JSON.stringify(step.state))).toEqual(step.state);
60	    expect(game.publicView(step.state, true)).toEqual({ side: 'tails', outcome: 'tails', win: true });
61	  });
62	
63	  it('SC-10: start при несовпадении стороны даёт payout 0 и win: false', () => {
64	    const { rng, calls } = countingRng([0.75]);
65	    const step: any = game.start({ bet: 4, params: { side: 'heads' }, rng });
66	    expect(calls()).toBe(1);
